# existing g; scan maximal 4-run with 9 at either side
out=[r[:] for r in g]
for i in range(10):
 for j in range(19):
  if g[i][j]!=4: continue
  for di,dj in [(0,1),(1,0)]:
   pi,pj=i-di,j-dj
   if 0<=pi<10 and 0<=pj<19 and g[pi][pj]==4: continue
   cells=[];x,y=i,j
   while 0<=x<10 and 0<=y<19 and g[x][y]==4:
    cells.append((x,y));x+=di;y+=dj
   if 0<=x<10 and 0<=y<19 and g[x][y]==9 and 0<=pi<10 and 0<=pj<19 and g[pi][pj]==9:
    for a,b in cells:out[a][b]=2
